"use client";

import { MessageCircle } from "lucide-react";
import { buildPreviewExchanges } from "../../lib/workspace/format";
import { useDraft } from "./DraftProvider";
import styles from "./pages.module.css";

/** Shows how the current settings would shape replies. Text is assembled from the draft, not generated by AI. */
export default function AssistantPreview() {
  const { draft, readOnly } = useDraft();
  const name = draft.assistant.name.trim() || "Asistent";
  const exchanges = buildPreviewExchanges(draft);

  return (
    <aside className={styles.previewPanel} aria-labelledby="assistant-preview-title">
      <div className={styles.previewHeader}>
        <span className={styles.previewIcon}><MessageCircle size={17} aria-hidden="true" /></span>
        <div>
          <h2 id="assistant-preview-title">Primer odgovora</h2>
          <p>{readOnly ? "Sastavljen iz trenutnih podešavanja." : "Menja se dok uređujete podešavanja."}</p>
        </div>
      </div>
      <div className={styles.previewThread}>
        <div className={`${styles.bubble} ${styles.assistantBubble}`}>
          <span className={styles.bubbleSpeaker}>{name} · pozdrav</span>
          <p>{draft.assistant.greeting.trim() || <em>Pozdrav još nije unet.</em>}</p>
        </div>
        {exchanges.map((exchange) => (
          <div key={exchange.question} className={styles.exchange}>
            <div className={`${styles.bubble} ${styles.callerBubble}`}>
              <span className={styles.bubbleSpeaker}>Klijent</span>
              <p>{exchange.question}</p>
            </div>
            <div className={`${styles.bubble} ${styles.assistantBubble}`}>
              <span className={styles.bubbleSpeaker}>{name}</span>
              <p>{exchange.answer}</p>
              <span className={styles.bubbleSource}>{exchange.note}</span>
            </div>
          </div>
        ))}
      </div>
      <p className={styles.previewNote}>Pregled je sastavljen iz vaših podešavanja po unapred zadatim pravilima. Ne koristi AI model i ne upućuje pozive.</p>
    </aside>
  );
}
